insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18903')::uuid, md5('building-dorotheenstrasse-48-22301')::uuid, '18903', 'kompakte-bueroflaeche-im-dorotheen-palais-in-winterhude-18903', 'Kompakte Bürofläche im Dorotheen-Palais in Winterhude', 'Das Dorotheen-Palais befindet sich im beliebten Stadtteil Winterhude nur einen kurzen Fußweg von der Außenalster entfernt. Sämtliche Geschäfte des täglichen Bedarfs sowie …', 'Das Dorotheen-Palais befindet sich im beliebten Stadtteil Winterhude nur einen kurzen Fußweg von der Außenalster entfernt. Sämtliche Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants sind nach wenigen Metern erreicht. Im direkten Umfeld fahren mehrere Buslininen und auch die nahe gelegene U-Bahnstation Sierichstraße sorgt für eine gute Anbindung an das öffentliche Verkehrsnetz.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-18903-1')::uuid, md5('property-18903')::uuid, 'Mietfläche', 185, 17.8, null, 'filemaker', '18903-1') on conflict (id) do nothing;
