insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21180')::uuid, md5('building-holzdamm-40-20099')::uuid, '21180', 'flaeche-im-historischen-altbau-in-st-georg-21180', 'Fläche im historischen Altbau in St. Georg', 'Das aufwendig modernisierte Bürogebäude befindet sich in verkehrsgünstiger Lage nahe der Außenalster im lebendigen Szeneviertel St. Georg. Der Hauptbahnhof mit allen Nah- und …', 'Das aufwendig modernisierte Bürogebäude befindet sich in verkehrsgünstiger Lage nahe der Außenalster im lebendigen Szeneviertel St. Georg. Der Hauptbahnhof mit allen Nah- und Fernverbindungen sichert einen sehr guten Anschluss an den ÖPNV. Im direkten Umfeld lädt die Lange Reihe mit vielseitigen Einkaufsmöglichkeiten und zahlreichen Cafés und Restaurants zum Bummeln ein. Die kompakte Fläche im Souterrain mit ca. 110 qm teilt sich in zwei große Räume mit separatem Vorflur, einer Küche und zwei Bädern. Zusätzlich führt eine interne Treppe zu zwei weiteren Büroflächen mit einer Gesamtgröße von ca. 75 qm im Kellergeschoss. Ein PKW-Stellplatz kann bei Bedarf am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_21180.pdf', null, 'filemaker', '21180') on conflict (id) do nothing;
