insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23620')::uuid, md5('building-ferdinandstrasse-29-33-20095')::uuid, '23620', 'gepflegte-bueroflaeche-im-klassischem-kontorhaus-23620', 'Gepflegte Bürofläche im klassischem Kontorhaus', 'Das hochwertig ausgebaute Kontorhaus befindet sich in zentraler Lage zwischen Ballindamm und Mönckebergstraße. Die Binnenalster, das Rathaus und die Innenstadt mit zahlreichen …', 'Das hochwertig ausgebaute Kontorhaus befindet sich in zentraler Lage zwischen Ballindamm und Mönckebergstraße. Die Binnenalster, das Rathaus und die Innenstadt mit zahlreichen Flaniermeilen und Einkaufsstraßen sind fußläufig schnell erreicht. Die Anbindung an den ÖPNV ist durch den nahe gelegenen Hauptbahnhof gesichert. Die aktuelle Ausstattung der Mietfläche umfasst u.a. Teppichbodenbelag, integrierte Deckenbeleuchtung sowie eine kleine Teeküche. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können im direkten Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 186, 658, 'https://www.buerohamburg.de/objects/pdf/BHI_23620.pdf', null, 'filemaker', '23620') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23620-1')::uuid, md5('property-23620')::uuid, 'Mietfläche', 186, 18.2, null, 'filemaker', '23620-1') on conflict (id) do nothing;
