insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-21691')::uuid, md5('building-colonnaden-51-20354')::uuid, '21691', 'colonnaden-moderne-bueroflaeche-mit-balkon-21691', 'Colonnaden: Moderne Bürofläche mit Balkon', 'Das Bürogebäude befindet sich in exponierter Innenstadtlage in den Colonnaden. Der in wenigen Gehminuten erreichbare Dammtorbahnhof, die U-Bahn-Station Stephansplatz sowie diverse …', 'Das Bürogebäude befindet sich in exponierter Innenstadtlage in den Colonnaden. Der in wenigen Gehminuten erreichbare Dammtorbahnhof, die U-Bahn-Station Stephansplatz sowie diverse Buslinien gewährleisten eine hervorragende Anbindung an den öffentlichen Personennahverkehr. Vielfältige Einkaufsmöglichkeiten sowie zahlreiche Cafés und Restaurants unterstreichen die Attraktivität dieser begehrten Innenstadtlage.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-21691-1')::uuid, md5('property-21691')::uuid, 'Mietfläche', 191, 28, null, 'filemaker', '21691-1') on conflict (id) do nothing;
