insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-14700')::uuid, md5('building-am-kaiserkai-10-20457')::uuid, '14700', 'repraesentative-bueroflaeche-mit-blick-auf-den-historischen-hafen-14700', 'Repräsentative Bürofläche mit Blick auf den historischen Hafen', 'Das neuwertige Büro- und Geschäftsgebäude befindet sich in bester Hafencitylage in der Nähe der Elbphilharmonie. Die Anbindung an den ÖPNV ist durch die nur wenige Gehminuten …', 'Das neuwertige Büro- und Geschäftsgebäude befindet sich in bester Hafencitylage in der Nähe der Elbphilharmonie. Die Anbindung an den ÖPNV ist durch die nur wenige Gehminuten entfernte U-Bahn Überseequartier und verschiedene Buslinien gewährleistet. Im direkten Umfeld befinden sich diverse Cafés, Restaurants, Einkaufmöglichkeiten und auch die Hamburger Innenstadt ist fußläufig gut zu erreichen. Zur Ausstattung der repräsentativen Mieteinheit zählen u.a. Holz- und Teppichboden, bodentiefe Glastrennwände, eine offene Pantry sowie getrennte WC-Einheiten. PKW-Stellplätze stehen in der hauseigenen Tiefgarage zur Verfügung.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['wasserblick']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_14700.pdf', null, 'filemaker', '14700') on conflict (id) do nothing;
