insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23431')::uuid, md5('building-hohe-bleichen-18-20-20354')::uuid, '23431', 'schoene-bueroflaeche-in-bester-innenstadtlage-23431', 'Schöne Bürofläche in bester Innenstadtlage', 'Das stadtbekannte Hanse Viertel befindet sich in bester Hamburger Innenstadtlage nahe der Binnenalster und dem Rathaus. Die ÖPNV-Anbindung ist durch die nahegelegene S- und …', 'Das stadtbekannte Hanse Viertel befindet sich in bester Hamburger Innenstadtlage nahe der Binnenalster und dem Rathaus. Die ÖPNV-Anbindung ist durch die nahegelegene S- und U-Bahnstation Jungfernstieg sowie diverse Buslinien gewährleistet. Das attraktive Angebot an niveauvollen Einkaufsmöglichkeiten, guten Restaurants und charmanten Cafés unterstreicht das besondere Flair dieser zentralen Lage. Die helle Bürofläche wird über ein ansprechendes Treppenhaus mit zwei Personenaufzügen erschlossen und verfügt aktuell über Amticofußboden, außen liegenden elektrischen Sonnenschutz, Bodentanks, eine Pantry sowie getrennte WC-Einheiten. Die weitere Aufteilung und Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenansichten stammen aus einer ähnlichen Fläche im Objekt. PKW-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_23431.pdf', null, 'filemaker', '23431') on conflict (id) do nothing;
