insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24817')::uuid, md5('building-vorsetzen-32-39-20459')::uuid, '24817', 'altstadt-modernes-buero-an-der-elbe-24817', 'Altstadt: Modernes Büro an der Elbe', 'Das markante Bürogebäude befindet sich in bester Citylage direkt an der Elbe. Die U-Bahnstation Baumwall liegt nur wenige Fußminuten entfernt und sichert eine sehr gute Anbindung …', 'Das markante Bürogebäude befindet sich in bester Citylage direkt an der Elbe. Die U-Bahnstation Baumwall liegt nur wenige Fußminuten entfernt und sichert eine sehr gute Anbindung an das öffentliche Verkehrsnetz. Zahlreiche kleine Geschäfte und eine großes Angebot an Cafés und Restaurants im angrenzenden Portugiesenviertel unterstreichen die Attraktivität dieser lebendigen Lage. Die helle Bürofläche erschließt sich über ein modernes Foyer. Die derzeitige Ausstattung umfasst bodentiefe Fenster, Beleuchtungssysteme, Bodentanks, eine Kühlung über Betonkernaktivierung, sowie separate WC-Einheiten. Die weitere Ausstattung erfolgt in Absprache mit dem zukünftigen Mieter. Die Innenbilder sind beispielhaft gewählt. Ein PKW- Stellplätze kann in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 204, 647, 'https://www.buerohamburg.de/objects/pdf/BHI_24817.pdf', null, 'filemaker', '24817') on conflict (id) do nothing;
