insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24069')::uuid, md5('building-friedrich-ebert-damm-112-22047')::uuid, '24069', 'wandsbek-zentrales-buero-hinter-moderner-fassade-24069', 'Wandsbek: Zentrales Büro hinter moderner Fassade', 'Das Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage von Hamburg Wandsbek mit einer guten Anbindung an das öffentliche Verkehrsnetz. Kleine Cafés, Restaurants …', 'Das Büro- und Geschäftsgebäude befindet sich in verkehrsgünstiger Lage von Hamburg Wandsbek mit einer guten Anbindung an das öffentliche Verkehrsnetz. Kleine Cafés, Restaurants und Unterhaltungsmöglichkeiten sind fußläufig erreichbar. Seine besondere Gestaltung hebt es gegenüber anderen Objekten in der Nachbarschaft hervor. Die hier angebotene Bürofläche kann nach Absprache mit dem zukünftigen Mieter neu aufgeteilt und ausgestattet werden. PKW-Stellplätze müssten im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_24069.pdf', null, 'filemaker', '24069') on conflict (id) do nothing;
