insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-4083')::uuid, md5('building-beim-alten-gaswerk-5-22761')::uuid, '4083', 'charmante-bueroflaeche-im-otto-von-bahrenpark-4083', 'Charmante Bürofläche im Otto-von-Bahrenpark', 'Der ehemalige Kohleturm im Otto-von-Bahrenpark befindet sich im urbanen Bahrenfeld in ruhiger Lage. Die Anbindung an den ÖPNV ist durch die S-Bahnstation Bahrenfeld sehr gut. …', 'Der ehemalige Kohleturm im Otto-von-Bahrenpark befindet sich im urbanen Bahrenfeld in ruhiger Lage. Die Anbindung an den ÖPNV ist durch die S-Bahnstation Bahrenfeld sehr gut. Diverse Einkaufsmöglichkeiten und ein vielfältiges gastronomisches Angebot mit zahlreichen Cafés, Bars und Restaurants erhöhen die Attraktivität dieser mittlerweile sehr beliebten Hamburger Lage. Die loftartig ausgebaute Erdgeschossfläche verfügt über zum Teil bodentiefe Fenster, einen Holzfußboden und eine modern ausgebaute Pantry. Lichtdurchlässige Glastüren und moderne Beleuchtungskörper gehören ebenfalls zur Ausstattung. PKW-Stellplätze können nach Rücksprache am Objekt angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', array['erdgeschoss', 'stellplaetze']::text[], 193, 2728, 'https://www.buerohamburg.de/objects/pdf/BHI_4083.pdf', null, 'filemaker', '4083') on conflict (id) do nothing;
