insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-12096')::uuid, md5('building-stadthausbruecke-1-3-20355')::uuid, '12096', 'flexibel-aufteilbare-ladenflaeche-in-bester-citylage-12096', 'Flexibel aufteilbare Ladenfläche in bester Citylage', 'Der Fleethof befindet sich in bester Innenstadtlage in unmittelbarer Nachbarschaft zum Neuen Wall. Die U- und S-Bahnstationen Stadthausbrücke und Rödingsmarkt sind nach wenigen …', 'Der Fleethof befindet sich in bester Innenstadtlage in unmittelbarer Nachbarschaft zum Neuen Wall. Die U- und S-Bahnstationen Stadthausbrücke und Rödingsmarkt sind nach wenigen Metern erreicht. Das Umfeld ist geprägt durch alle Geschäfte des täglichen Bedarfs, diverse Einkaufspassagen sowie zahlreiche gastronomische Angebote. Das Gebäude verfügt über einen repräsentativen, glasüberdachten Innenhof mit Pförtnerdienst. Zur Ausstattung der flexibel aufteilbaren Ladenfläche zählen Stäbchenparkett und Teppichfußboden, Beleuchtungssysteme, Glastrennwände, hohe Decken, eine Pantry und getrennte WC-Einheiten. Die zukünftige Aufteilung und Ausstattung erfolgt in Absprache mit dem neuen Mieter. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-12096-1')::uuid, md5('property-12096')::uuid, 'Mietfläche', 212, 22.5, null, 'filemaker', '12096-1') on conflict (id) do nothing;
