insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-13480')::uuid, md5('building-grosser-burstah-25-20457')::uuid, '13480', 'helle-bueroflaeche-in-rathausnaehe-13480', 'Helle Bürofläche in Rathausnähe', 'Das Büro- und Geschäftshaus befindet sich in bester Citylage in unmittelbarer Nähe zu Rathausmarkt und Mönckebergstraße. Zahlreiche Restaurants, Cafes und alle Geschäfte des …', 'Das Büro- und Geschäftshaus befindet sich in bester Citylage in unmittelbarer Nähe zu Rathausmarkt und Mönckebergstraße. Zahlreiche Restaurants, Cafes und alle Geschäfte des täglichen Bedarfs befinden sich im direkten Umfeld. Die U- und S-Bahnstationen Rödingsmarkt, Stadthausbrücke und Rathausmarkt sind nach wenigen Fußminuten erreicht. Über die modernisierten Eingangsbereiche mit Personenfahrstühlen sind die jeweiligen Etagen zu erreichen. Die hellen und funktionalen Mieteinheiten können in Absprache mit dem zukünftigen Mieter aufgeteilt und ausgestattet werden. Die Bilder stammen aus einer modernisierten Einheit im Gebäude. PKW-Stellplätze können in der Umgebung angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 212, 244, 'https://www.buerohamburg.de/objects/pdf/BHI_13480.pdf', null, 'filemaker', '13480') on conflict (id) do nothing;
