insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-045')::uuid, md5('building-buttstrasse-3-22767')::uuid, '045', 'moderne-bueroflaeche-in-ruhiger-lage-am-elbufer-045', 'Moderne Bürofläche in ruhiger Lage am Elbufer', 'Das moderne Büro- und Geschäftsgebäude befindet sich direkt am Hafenbecken im belebten Stadtteil Altona-Altstadt. Die Anbindung an den ÖPNV ist durch die nahegelegene …', 'Das moderne Büro- und Geschäftsgebäude befindet sich direkt am Hafenbecken im belebten Stadtteil Altona-Altstadt. Die Anbindung an den ÖPNV ist durch die nahegelegene S-Bahnstation Königstraße, die Buslinie 111 und die Hadag-Fähre gewährleistet. Das direkte Umfeld ist geprägt von zahlreichen Geschäften und einem vielseitigen gastronomischen Angebot. Zusätzlich siedeln sich in der Großen Elbstraße immer mehr exklusive Delikatessen- und Einzelhändler an. Die weitere Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. Pkw-Stellplätze können im Umfeld angemietet werden. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 219, 220, 'https://www.buerohamburg.de/objects/pdf/BHI_045.pdf', null, 'filemaker', '045') on conflict (id) do nothing;
