insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24609')::uuid, md5('building-nedderfeld-98-22529')::uuid, '24609', 'eppendorf-helle-loftige-bueroflaeche-in-nedderfeld-24609', 'Eppendorf: Helle loftige Bürofläche in Nedderfeld', 'Das markante Bürogebäude befindet sich im Nedderfeld zwischen dem Tarpenbeker Ufer und der Universitätsklinik Eppendorf. Sowohl der Anschluss Stellingen an die A7 als auch der …', 'Das markante Bürogebäude befindet sich im Nedderfeld zwischen dem Tarpenbeker Ufer und der Universitätsklinik Eppendorf. Sowohl der Anschluss Stellingen an die A7 als auch der Flughafen Fuhlsbüttel sind in wenigen Fahrminuten erreicht. Der Anschluss an den ÖPNV ist durch eine sich am Objekt befindende Buslinie gesichert. Diverse Cafés und Restaurans beleben das Umfeld und sorgen für abwechslungsreiche Mittagspausen. Die lichtdurchflutete, loftige Bürofläche befindet sich im 1. Obergeschoss und erschließt sich über ein modernes Foyer mit Personen- und Lastenaufzug. Die aktuellen Ausstattung umfasst Teppichboden, Beleuchtungssysteme, innenliegender Sonnenschutz, Klimatisierung und separate WC-Einheiten. Ein Pantryanschluss ist ebenfalls vorhanden. PKW-Stellplätze können auf dem Hof sowie in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['lastenaufzug', 'stellplaetze']::text[], 220, 1100, 'https://www.buerohamburg.de/objects/pdf/BHI_24609.pdf', null, 'filemaker', '24609') on conflict (id) do nothing;
