insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25271')::uuid, md5('building-speersort-4-6-20095')::uuid, '25271', 'altstadt-helle-bueroflaeche-in-bester-citylage-25271', 'Altstadt: Helle Bürofläche in bester Citylage', 'Das Büro- und Geschäftsgebäude befindet sich in zentraler Hamburger Innenstadtlage nur wenige Meter von der Mönckebergstraße entfernt. Das direkte Umfeld bietet gute …', 'Das Büro- und Geschäftsgebäude befindet sich in zentraler Hamburger Innenstadtlage nur wenige Meter von der Mönckebergstraße entfernt. Das direkte Umfeld bietet gute Einkaufsmöglichkeiten und eine Vielzahl an Cafés und Restaurants. Sämtliche U- und S-Bahnanbindungen sind fußläufig über die Station Jungfernstieg und den nahegelegenen Hauptbahnhof zu erreichen. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25271-1')::uuid, md5('property-25271')::uuid, 'Mietfläche', 221, 18.5, null, 'filemaker', '25271-1') on conflict (id) do nothing;
