insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24784')::uuid, md5('building-poststrasse-37-20354')::uuid, '24784', 'moderne-bueroflaeche-im-historischen-koernerhaus-24784', 'Moderne Bürofläche im historischen Körnerhaus', 'Das repräsentative Geschäftshaus befindet sich in bester Hamburger Innenstadtlage am Gänsemarkt. Der Jungfernstieg mit allen U- und S-Bahnanschlüssen sowie die Binnenalster sind …', 'Das repräsentative Geschäftshaus befindet sich in bester Hamburger Innenstadtlage am Gänsemarkt. Der Jungfernstieg mit allen U- und S-Bahnanschlüssen sowie die Binnenalster sind fußläufig schnell erreicht. Zahlreiche Geschäfte des täglichen Bedarfs sowie Cafés und Restaurants befinden sich in direkter Nachbarschaft. Die Bürofläche wird über ein historisches Foyer und einen gläsernen Aufzug erschlossen. Die vakante Einheit befindet sich im 2. Obergeschoss und ist derzeitig durch Leichtbauwände in Einzel- und Teambüros unterteilt. Die aktuelle Ausstattung umfasst einen Laminatfußboden, eine EDV-Verkabelung, eine Pantry sowie separate Sanitäreinheiten. PKW-Stellplätze können in der Umgebung angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', '{}'::text[], 198, 222, 'https://www.buerohamburg.de/objects/pdf/BHI_24784.pdf', null, 'filemaker', '24784') on conflict (id) do nothing;
