insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24720')::uuid, md5('building-moenckebergstrasse-5-20095')::uuid, '24720', 'city-charmante-bueroflaeche-in-toplage-24720', 'City: Charmante Bürofläche in Toplage', 'Der markante Altbau befindet sich im Herzen der Hamburger Innenstadt an der bekannten Mönckebergstraße. Alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants …', 'Der markante Altbau befindet sich im Herzen der Hamburger Innenstadt an der bekannten Mönckebergstraße. Alle Geschäfte des täglichen Bedarfs sowie zahlreiche Cafés und Restaurants befinden sich im direkten Umfeld. Die Anbindung an das öffentliche Verkehrsnetz ist durch den nur wenige Gehminuten entfernten Hauptbahnhof, mit Anschluss an alle S- und U-Bahnlinien sowie die Züge der Deutschen Bahn, als hervorragend zu bezeichnen. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-24720-1')::uuid, md5('property-24720')::uuid, 'Mietfläche', 224, 30, null, 'filemaker', '24720-1') on conflict (id) do nothing;
