insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-18015')::uuid, md5('building-lippeltstrasse-1-20097')::uuid, '18015', 'vor-den-toren-der-hafencity-das-kontorhaus-am-grossmarkt-18015', 'Vor den Toren der Hafencity - das Kontorhaus am Großmarkt', 'Das markante Bürogebäude befindet sich in repräsentativer und verkehrsgünstiger Lage in der HafenCity-Ost und bietet einen herrlichen Blick über die Hamburger Innenstadt, die …', 'Das markante Bürogebäude befindet sich in repräsentativer und verkehrsgünstiger Lage in der HafenCity-Ost und bietet einen herrlichen Blick über die Hamburger Innenstadt, die Elbbrücken, die HafenCity und die Speicherstadt. Die Anbindung an das öffentliche Verkehrsnetz ist nicht zuletzt durch die unmittelbare Nähe zum Hamburger Hauptbahnhof als sehr gut zu bezeichnen. Die Mietfläche wird in Absprache mit dem zukünftigen Mieter ausgebaut und ausgestattet. Pkw-Stellplätze stehen in der hauseigenen Tiefgarage zur Anmietung bereit. Diese Innenbilder sind beispielhaft gewählt.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['stellplaetze']::text[], 225, 247, 'https://www.buerohamburg.de/objects/pdf/BHI_18015.pdf', null, 'filemaker', '18015') on conflict (id) do nothing;
