insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-23934')::uuid, md5('building-colonnaden-25-20354')::uuid, '23934', 'gut-aufgeteilte-bueroflaeche-in-zentraler-toplage-23934', 'Gut aufgeteilte Bürofläche in zentraler Toplage', 'Zwischen Gänsemarkt und Binnenalster, in einer der begehrtesten Hamburger Geschäftslagen, befindet sich dieses markante Bürogebäude. Das Objekt beeindruckt mit einer historischen …', 'Zwischen Gänsemarkt und Binnenalster, in einer der begehrtesten Hamburger Geschäftslagen, befindet sich dieses markante Bürogebäude. Das Objekt beeindruckt mit einer historischen Fassade und einem repräsentativen Eingangsbereich mit Personenaufzug. Die Haltestelle Jungfernstieg mit Anbindung an sämtliche U- und S-Bahnlinien sowie diverse Busverbindungen ist in wenigen Minuten erreichbar. Das lebendige Umfeld bietet zahlreiche Geschäfte des täglichen Bedarfs, Restaurants und Cafés.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-23934-1')::uuid, md5('property-23934')::uuid, 'Mietfläche', 236, 32, null, 'filemaker', '23934-1') on conflict (id) do nothing;
